arguments.argument:
//Variable "myroom" stands for the room the animatronic is located
if goingback = 0
    movetime -= 1
else
    backtimer -= 1
//When "movetime" is less than 0, it'll make the animatronic move from one room to another and breaks temporarily the cameras.
if movetime < 0
{
    movetime = 30+random(170)
    //Makes animatronic move from one room to another
    if myroom = 0 //If this animatronic is located on Show Stage, move to Dining Area
    {
        if obj_mapcamera1a.on = 1 or obj_mapcamera11.on = 1
        and instance_exists(obj_camera)
        {
            with obj_mapcamera1a broken = 1
            with obj_mapcamera1a alarm[0] = 150
            with obj_mapcamera11 broken = 1
            with obj_mapcamera11 alarm[0] = 150
            sound_play(snd_static)
        }
        myroom = 1
    }
    else if myroom = 1
    {
        if obj_mapcamera11.on = 1 or obj_mapcamera11.on = 1
        and instance_exists(obj_camera)
        {
            with obj_mapcamera11 broken = 1
            with obj_mapcamera11 alarm[0] = 150
            with obj_mapcamera11 broken = 1
            with obj_mapcamera11 alarm[0] = 150
            sound_play(snd_static)
        }
        myroom = 2
    }
    else if myroom = 2
    {
        if obj_mapcamera11.on = 1
        and instance_exists(obj_camera)
        {
            with obj_mapcamera11 broken = 1
            with obj_mapcamera11 alarm[0] = 150
            sound_play(snd_static)
        }
        myroom = 3

        {

        }
    }
    else if myroom = 3 //If this animatronic is located on office's right door, makes player unable to use right doors or right light buttons
        myroom = 4
}
if backtimer < 0 //Leaves office when right door is closed, and moves back to Dining Area
{
    backtimer = mybacktimer
    myroom = 3
    {
        if obj_mapcamera1a.on = 1 
        and instance_exists(obj_camera)
        {
            with obj_mapcamera1a broken = 1
            with obj_mapcamera1a alarm[0] = 150
            sound_play(snd_static)
        }

        movetime = mymovetime
        myroom = 1
        sound_play(snd_freddy_run)
    }
}
